"""Quantitative corridor for the d = 3 forbidden-cube problem.

Prints, for a range of ground-set sizes n, the three quantities that frame
La(n, B_3) in units of the central binomial coefficient C(n, floor(n/2)):

  * the levels lower bound         : the largest sum of 3 consecutive binomials;
  * the sharpened chain bound      : ((2^d-1)m+1)/(m+1)   for n = 2m,
                                     ((2^d-1)m+4)/(m+2)   for n = 2m+1;
  * the classical chain bound      : 2^d - 1 = 7;
  * the layer-optimal Lubell bound : the sum of the 7 largest binomials, which
                                     is the very best any argument using only
                                     the Lubell mass can deliver;
  * the conjectured value          : 4.

The output makes visible the two facts that organise the whole subject: the
sharpened bound improves the chain bound only at rate Theta(1/n), and the
layer-optimal bound, though far better for moderate n, still climbs to 7.
"""

from __future__ import annotations

from fractions import Fraction
from math import comb
from typing import List


def central(n: int) -> int:
    """C(n, floor(n/2))."""
    return comb(n, n // 2)


def levels_lower_bound(n: int, d: int) -> int:
    """Largest sum of d consecutive binomial coefficients of order n."""
    if d >= n + 1:
        return 2 ** n
    return max(sum(comb(n, i) for i in range(a, a + d)) for a in range(0, n + 2 - d))


def sharpened_bound(n: int, d: int) -> Fraction:
    """Sharpened chain bound as an exact rational."""
    k = 2 ** d - 1
    if n % 2 == 0:
        m = n // 2
        if m == 0:
            return Fraction(k * central(n))
        return Fraction(k * m + 1, m + 1) * comb(2 * m, m)
    m = (n - 1) // 2
    if m == 0:
        return Fraction(k * central(n))
    return Fraction(k * m + 4, m + 2) * comb(2 * m + 1, m)


def layer_optimal(n: int, budget: int) -> int:
    """Sum of the ``budget`` largest binomial coefficients of order n."""
    sizes: List[int] = sorted((comb(n, j) for j in range(n + 1)), reverse=True)
    return sum(sizes[:budget])


def main() -> None:
    d = 3
    print(f"Corridor for La(n, B_{d}) in units of C(n, floor(n/2))\n")
    header = f"{'n':>4} {'C(n)':>9} {'levels LB':>10} {'sharpened':>10} " \
             f"{'layer-opt':>10} {'chain':>8} {'conj':>6}"
    print(header)
    print("-" * len(header))
    for n in list(range(2, 21)) + [30, 40, 60, 100]:
        c = central(n)
        lb = levels_lower_bound(n, d) / c
        sh = float(sharpened_bound(n, d)) / c
        lo = layer_optimal(n, 2 ** d - 1) / c
        print(f"{n:>4} {c:>9} {lb:>10.3f} {sh:>10.3f} {lo:>10.3f} {7.0:>8.3f} {4.0:>6.3f}")
    print("\nAsymptotics: levels LB -> 3, sharpened -> 7, layer-optimal -> 7.")
    print("The conjecture asserts that the truth is at most 4.")


if __name__ == "__main__":
    main()

