"""Marker-block construction: an explicit Boolean cube inside d+1 complete levels."""

from __future__ import annotations

from typing import Dict, List, Sequence


def popcount(x: int) -> int:
    """Cardinality of the set encoded by the bitmask ``x``."""
    return bin(x).count("1")


def is_subset(a: int, b: int) -> bool:
    """Containment test for bitmask-encoded sets: a subseteq b."""
    return a & ~b == 0


def complete_levels_copy(n: int, sizes: Sequence[int]) -> Dict[int, int]:
    """Build a weak copy of B_d from the complete levels of sizes i_0 < ... < i_d.

    Reserve the d largest points of [n] as markers m_1 < ... < m_d and let L_j be
    the block of the j smallest points.  For S subseteq [d] set

        f(S) = L_{i_{|S|} - |S|}  union  { m_t : t in S }.

    Then |f(S)| = i_{|S|}, so f(S) lies in one of the prescribed levels; f is
    monotone because i_{j+1} - (j+1) >= i_j - j makes the low blocks nested while
    the marker parts are nested by construction; and f is injective because the
    markers read off S exactly.

    Complexity: O(2^d) set constructions, each O(n) bit operations.
    """
    d = len(sizes) - 1
    if d > n:
        raise ValueError("need d <= n")
    if any(sizes[i] >= sizes[i + 1] for i in range(d)) or sizes[-1] > n:
        raise ValueError("sizes must be strictly increasing and at most n")
    markers: List[int] = [n - d + t for t in range(d)]
    out: Dict[int, int] = {}
    for s in range(1 << d):
        k = popcount(s)
        mask = (1 << (sizes[k] - k)) - 1
        for t in range(d):
            if s >> t & 1:
                mask |= 1 << markers[t]
        out[s] = mask
    return out


def verify_copy(f: Dict[int, int], d: int) -> bool:
    """Check injectivity and containment-preservation of a candidate copy of B_d."""
    if len(set(f.values())) != 1 << d:
        return False
    return all(
        is_subset(f[s], f[t])
        for s in range(1 << d)
        for t in range(1 << d)
        if is_subset(s, t)
    )


if __name__ == "__main__":
    for n, sizes in ((6, [0, 2, 5]), (7, [1, 3, 4, 7]), (9, [0, 4, 5, 9])):
        d = len(sizes) - 1
        f = complete_levels_copy(n, sizes)
        assert verify_copy(f, d)
        print(f"n = {n}, levels {sizes}: verified copy of B_{d}, "
              f"image sizes {sorted(popcount(v) for v in f.values())}")
